import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color, DoubleSide } from "three/webgpu";
import { uv, vec3, mix } from "three/tsl";
import gsap from "gsap";

/**
 * @typedef {object} NodeConfig
 * @typedef {object} NodeContext
 */

/**
 * Creates a premium pricing card node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color, DoubleSide } = ctx.THREE;

  /*** Helpers ***/
  const toColor = (hex) => new Color(hex);
  const createPlane = (w, h, material, z = 0) => {
    const geo = new PlaneGeometry(w, h);
    const mesh = new Mesh(geo, material);
    mesh.position.set(0, 0, z);
    return mesh;
  };
  const disposeAll = (objs) => {
    objs.forEach((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) obj.material.dispose();
    });
  };

  /*** Group root ***/
  const root = new Group();
  root.scale.set(1.04, 1.04, 1.04); // start scaled for settle animation

  /*** Card dimensions ***/
  const CARD_W = 2.4;
  const CARD_H = 3.2;
  const BORDER_THICK = 0.006;
  const HEADER_H = 0.08;
  const CTA_W = 1.4;
  const CTA_H = 0.36;
  const PAD = 0.5; // interior padding
  const FEATURE_ROW_H = 0.375; // per spec
  const BORDER_COLOR = "#2a2a33";
  const SURFACE_COLOR = "#16161d";
  const INK_COLOR = "#16161d";
  const ACCENT_COLOR = "#ff2a38";

  /*** Materials ***/
  const bgMat = new MeshStandardNodeMaterial({
    color: toColor(SURFACE_COLOR),
    metalness: 0,
    roughness: 1,
  });

  const borderMat = new MeshStandardNodeMaterial({
    color: toColor(BORDER_COLOR),
    metalness: 0,
    roughness: 1,
  });

  const headerMat = new MeshStandardNodeMaterial({
    color: toColor(SURFACE_COLOR),
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
  });

  // CTA gradient material
  const cTop = toColor("#ff4450");
  const cBot = toColor("#c1121f");
  const gradientNode = mix(vec3(cTop), vec3(cBot), uv().y);
  const ctaMat = new MeshBasicNodeMaterial({
    colorNode: gradientNode,
    transparent: true,
    side: DoubleSide,
  });
  ctaMat.emissive = toColor(ACCENT_COLOR);
  ctaMat.emissiveIntensity = 1.5;

  /*** Geometry construction ***/
  // Background plane
  const bgPlane = createPlane(CARD_W, CARD_H, bgMat, 0);
  root.add(bgPlane);

  // Border plane (slightly larger, behind)
  const borderPlane = createPlane(CARD_W + BORDER_THICK * 2, CARD_H + BORDER_THICK * 2, borderMat, -0.001);
  root.add(borderPlane);

  // Header strip
  const headerPlane = createPlane(CARD_W, HEADER_H, headerMat, 0.001);
  headerPlane.position.set(0, CARD_H / 2 - HEADER_H / 2, 0);
  root.add(headerPlane);

  // CTA button
  const ctaPlane = createPlane(CTA_W, CTA_H, ctaMat, 0.002);
  const ctaY = -CARD_H / 2 + PAD + CTA_H / 2 + 0.5; // anchored 0.5 units above bottom edge
  ctaPlane.position.set(0, ctaY, 0);
  root.add(ctaPlane);

  /*** Text creation ***/
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const disposables = [bgPlane, borderPlane, headerPlane, ctaPlane];
  const featureTexts = [];

  // Utility to add text and set initial state
  const addText = (content, opts, pos) => {
    const txtObj = ctx.fontAtlas.createText(content, opts);
    txtObj.position.copy(pos);
    txtObj.visible = true;
    // Ensure material is transparent for fade animations
    txtObj.traverse((child) => {
      if (child.isMesh && child.material) {
        child.material.transparent = true;
        child.material.opacity = 0;
      }
    });
    root.add(txtObj);
    disposables.push(txtObj);
    return txtObj;
  };

  // Tier name
  const tierName = textItems.find((i) => i.role === "tier-name");
  if (tierName) {
    addText(tierName.text, {
      fontSize: tierName.typography?.fontSize ?? 20,
      color: INK_COLOR,
      align: "left",
      letterSpacingPx: tierName.typography?.letterSpacing ?? 0.08 * tierName.typography?.fontSize,
    }, new Vector3(-CARD_W / 2 + PAD, CARD_H / 2 - HEADER_H - PAD, 0));
  }

  // Price
  const price = textItems.find((i) => i.role === "price");
  if (price) {
    addText(price.text, {
      fontSize: price.typography?.fontSize ?? 62,
      color: INK_COLOR,
      align: "left",
    }, new Vector3(-CARD_W / 2 + PAD, CARD_H / 2 - HEADER_H - PAD - 0.3, 0));
  }

  // Caption (per month)
  const caption = textItems.find((i) => i.role === "caption");
  if (caption) {
    addText(caption.text, {
      fontSize: caption.typography?.fontSize ?? 9,
      color: INK_COLOR,
      align: "left",
    }, new Vector3(-CARD_W / 2 + PAD, CARD_H / 2 - HEADER_H - PAD - 0.7, 0));
  }

  // Feature rows
  const featureItems = textItems.filter((i) => i.role === "feature");
  const featureStartY = CARD_H / 2 - HEADER_H - PAD - 1.0; // start after previous texts
  featureItems.forEach((feat, idx) => {
    const y = featureStartY - idx * (FEATURE_ROW_H + BORDER_THICK);
    const txt = addText(feat.text, {
      fontSize: feat.typography?.fontSize ?? 13,
      color: INK_COLOR,
      align: "left",
      letterSpacingPx: feat.typography?.letterSpacing ?? 0,
    }, new Vector3(-CARD_W / 2 + PAD, y, 0));
    featureTexts.push(txt);

    // Hairline separator under each row except last
    if (idx < featureItems.length - 1) {
      const sepMat = new MeshStandardNodeMaterial({
        color: toColor("#23232b"),
        metalness: 0,
        roughness: 1,
      });
      const sep = createPlane(CARD_W - PAD * 2, BORDER_THICK, sepMat, 0);
      sep.position.set(0, y - FEATURE_ROW_H / 2 - BORDER_THICK / 2, 0);
      root.add(sep);
      disposables.push(sep);
    }
  });

  // CTA label
  const ctaLabel = textItems.find((i) => i.role === "cta-label");
  if (ctaLabel) {
    const txt = addText(ctaLabel.text, {
      fontSize: ctaLabel.typography?.fontSize ?? 13,
      color: INK_COLOR,
      align: "center",
      letterSpacingPx: ctaLabel.typography?.letterSpacing ?? 0.08 * ctaLabel.typography?.fontSize,
    }, new Vector3(0, ctaY, 0.001));
    // Center align by moving x = 0 already
    root.add(txt);
    disposables.push(txt);
  }

  /*** Animations ***/
  const timelines = [];

  // Settle scale animation
  const settle = gsap.timeline({ paused: true });
  settle.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: "cubic-bezier(0.165,0.84,0.44,1)",
  });
  settle.play();
  timelines.push(settle);

  // Feature rows fade-up stagger
  const featureTimeline = gsap.timeline({ paused: true });
  featureTexts.forEach((txt, i) => {
    txt.traverse((child) => {
      if (child.isMesh && child.material) {
        featureTimeline.from(
          child.material,
          {
            opacity: 0,
            y: "+=0.2",
            duration: 0.5,
            ease: "cubic-bezier(0.25,0.46,0.45,0.94)",
          },
          i * 0.08
        );
      }
    });
  });
  featureTimeline.play();
  timelines.push(featureTimeline);

  // CTA press animation handlers
  const ctaScale = { x: 1, y: 1, z: 1 };
  const pressDown = () => {
    gsap.to(ctaPlane.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: "cubic-bezier(0.175,0.885,0.32,1.275)",
    });
  };
  const pressUp = () => {
    gsap.to(ctaPlane.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: "cubic-bezier(0.175,0.885,0.32,1.275)",
    });
  };

  root.userData.handlers = {
    pressDown,
    pressUp,
  };

  // Cleanup
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    disposeAll(disposables);
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
